{
  "name": "magpie-zszapi",
  "version": "0.3.0",
  "description": "执算者AI (zszapi.com) for Magpie: paste one API Key to get GPT / Claude / DeepSeek chat models and gpt-image generation, with balance in ¥",
  "type": "module",
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  },
  "main": "./index.mjs",
  "exports": "./index.mjs",
  "files": [
    "index.mjs",
    "models.mjs",
    "queries.mjs",
    "usage.mjs",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "check": "node --check index.mjs && node --check models.mjs && node --check queries.mjs && node --check usage.mjs",
    "test": "node --test test/*.test.mjs",
    "smoke": "node scripts/smoke.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "magpie-plugin",
    "zszapi",
    "执算者AI",
    "sub2api",
    "provider"
  ],
  "license": "LGPL-3.0-or-later",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/teczt/magpie-zszapi.git"
  },
  "homepage": "https://github.com/teczt/magpie-zszapi#readme",
  "bugs": {
    "url": "https://github.com/teczt/magpie-zszapi/issues"
  },
  "engines": {
    "node": ">=20"
  },
  "magpie": {
    "name": "执算者AI",
    "summary": {
      "zh": "执算者AI（zszapi.com）官方插件：粘贴一个 API Key，自动获取 GPT / Claude / DeepSeek 对话模型并按原生协议调用，gpt-image 生图模型可用于 Magpie 生图，余额以人民币显示。",
      "en": "Official plugin for 执算者AI (zszapi.com): paste one API Key to discover GPT / Claude / DeepSeek chat models on their native APIs and gpt-image models for Magpie's image generation, with the wallet balance shown in CNY."
    },
    "icon": "data:image/png;base64,"
  }
}
